class Calculation:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def find_iteration(self):
        years = 0
        a, b = self.x, self.y
        while a <= b:
            a *= 3
            b *= 2
            years += 1
        return years

if __name__ == "__main__":
    x, y = map(int, input().split())
    calculation = Calculation(x, y)
    result = calculation.find_iteration()
    if result is not None:
        print(result)
